MANUAL_OVERRIDES = [
    # (name, start, end, size)
    ("FUN_0068f400", 0x0068F400, 0x0068F450, 80),
    ("FUN_0068f450", 0x0068F450, 0x0068F528, 216),
    ("FUN_006ec088", 0x006EC088, 0x006EC500, 1144),
    ("FUN_006ec500", 0x006EC500, 0x006EC8A4, 932),
    ("FUN_006f2440", 0x006F2440, 0x006F2540, 256),
    ("FUN_006f2540", 0x006F2540, 0x006F259C, 92),
    ("FUN_006f25a0", 0x006F25A0, 0x006F2630, 144),
    ("FUN_006f2630", 0x006F2630, 0x006F2638, 8),
    ("FUN_006f9f70", 0x006F9F70, 0x006FA668, 1784),
    ("FUN_006fa668", 0x006FA668, 0x006FA760, 248),
    ("FUN_006fa760", 0x006FA760, 0x006FA848, 232),
    ("FUN_00805880", 0x00805880, 0x008059C0, 320),
    ("FUN_008059c0", 0x008059C0, 0x008059C8, 8),
]


def load_base_rows():
    if os.path.exists(FALLBACK_BASE_CSV):
        with open(FALLBACK_BASE_CSV, "r", encoding="utf-8") as f:
            lines = [l.strip().split(",") for l in f if l.strip()]
    else:
        decomp = zlib.decompress(base64.b85decode(EMBEDDED_BASE_B85.strip())).decode("utf-8")
        lines = [l.strip().split(",") for l in decomp.splitlines() if l.strip()]

    rows = {}
    for r in lines[1:]:
        s = int(r[1], 16)
        rows[s] = {
            "Name": r[0],
            "Start": s,
            "End": int(r[2], 16),
            "Size": int(r[3]),
        }
    return rows


def analyze_elf_references(elf):
    jal_targets = set()
    j_targets = set()
    lui_targets = set()
    branch_map = defaultdict(list)
    vtable_targets = set()

    for off in range(0x100, len(elf) - 3, 4):
        pc = 0x4C0000 + off - 0x100
        w = int.from_bytes(elf[off:off+4], "little")
        op = w >> 26
        if op == 3:
            jal_targets.add((pc & 0xF0000000) | ((w & 0x03FFFFFF) << 2))
        elif op == 2:
            j_targets.add((pc & 0xF0000000) | ((w & 0x03FFFFFF) << 2))
        elif op in (1, 4, 5, 6, 7):
            simm = w & 0xFFFF
            if simm & 0x8000:
                simm -= 0x10000
            branch_map[pc + 4 + (simm << 2)].append(pc)
        elif op == 0x0F:
            rt = (w >> 16) & 0x1F
            imm_hi = w & 0xFFFF
            max_look = min(len(elf) - 3, off + 4 * 40)
            for off2 in range(off + 4, max_look, 4):
                w2 = int.from_bytes(elf[off2:off2+4], "little")
                op2 = w2 >> 26
                rs2 = (w2 >> 21) & 0x1F
                rt2 = (w2 >> 16) & 0x1F
                if op2 == 9 and rs2 == rt:
                    simm_lo = w2 & 0xFFFF
                    if simm_lo & 0x8000:
                        simm_lo -= 0x10000
                    lui_targets.add(((imm_hi << 16) + simm_lo) & 0xFFFFFFFF)
                elif op2 == 13 and rs2 == rt:
                    lui_targets.add((imm_hi << 16) | (w2 & 0xFFFF))
                if rt != 0:
                    if op2 == 0x0F and rt2 == rt:
                        break
                    if op2 == 0 and ((w2 >> 11) & 0x1F) == rt:
                        break
                    elif op2 in (8, 9, 10, 11, 12, 13, 14, 15, 32, 33, 35, 36, 37):
                        if rt2 == rt and rs2 != rt:
                            break

    for off in range(0, len(elf) - 7, 4):
        v = int.from_bytes(elf[off:off+4], "little")
        prev_w = int.from_bytes(elf[off-4:off], "little") if off >= 4 else 0
        next_w = int.from_bytes(elf[off+4:off+8], "little") if off + 8 <= len(elf) else 0
        p_ok = (0x004C0000 <= prev_w <= 0x00A27488 and prev_w % 4 == 0)
        n_ok = (0x004C0000 <= next_w <= 0x00A27488 and next_w % 4 == 0)
        if p_ok or n_ok:
            vtable_targets.add(v)

    return jal_targets, j_targets, lui_targets, branch_map, vtable_targets


def generate_functions(elf_path=DEFAULT_ELF):
    with open(elf_path, "rb") as f:
        elf = f.read()

    def get_u32(v):
        if 0x004C0000 <= v < 0x00A93700:
            off = v - 0x004C0000 + 0x100
            if off + 4 <= len(elf):
                return struct.unpack("<I", elf[off:off+4])[0]
        return 0

    jal_targets, j_targets, lui_targets, branch_map, vtable_targets = analyze_elf_references(elf)

    def is_referenced(addr, parent_s, parent_e):
        if addr in jal_targets or addr in j_targets or addr in lui_targets or addr in vtable_targets:
            return True
        for src in branch_map.get(addr, []):
            if not (parent_s <= src < parent_e):
                return True
        return False

    current_rows = load_base_rows()

    # Particionamiento iterativo de funciones referenciadas hasta convergencia
    while True:
        starts = set(current_rows.keys())
        missing_found = []
        for s_addr, r in list(current_rows.items()):
            name = r["Name"]
            if not name.startswith(("FUN_", "entry_", "thunk_")):
                continue
            s, e = r["Start"], r["End"]
            a = s
            while a + 16 <= e:
                w1 = get_u32(a)
                if w1 == 0x03E00008 or (w1 >> 26) == 2:
                    nxt = a + 4
                    b = nxt + 4
                    while b + 4 <= e:
                        ww = get_u32(b)
                        if ww != 0:
                            break
                        b += 4
                    if b in starts and b != s:
                        break
                    if s < b < e:
                        has_int_branch = any(s <= src < b for src in branch_map.get(b, []))
                        if not has_int_branch and is_referenced(b, s, e):
                            missing_found.append((s_addr, name, s, e, b))
                            break
                a += 4
        if not missing_found:
            break
        for s_addr, name, s, e, b in missing_found:
            current_rows[s_addr]["End"] = b
            current_rows[s_addr]["Size"] = b - s
            new_name = f"FUN_{b:08x}"
            current_rows[b] = {
                "Name": new_name,
                "Start": b,
                "End": e,
                "Size": e - b
            }
            for ms_addr, m_r in list(current_rows.items()):
                if ms_addr != b and m_r["Start"] < b < m_r["End"]:
                    m_r["End"] = b
                    m_r["Size"] = b - m_r["Start"]

    # FSM de carga de escena (FUN_00628640): extender a 0x628950 para cubrir la jump table 0x009E0180
    if 0x00628640 in current_rows:
        current_rows[0x00628640]["End"] = 0x00628950
        current_rows[0x00628640]["Size"] = 0x00628950 - 0x00628640

    # Overrides manuales de handlers
    for name, s, e, sz in MANUAL_OVERRIDES:
        current_rows[s] = {"Name": name, "Start": s, "End": e, "Size": sz}

    return sorted(current_rows.values(), key=lambda r: r["Start"])


def main():
    elf_path = sys.argv[1] if len(sys.argv) > 1 and not sys.argv[1].endswith(".csv") else DEFAULT_ELF
    out_csv = sys.argv[2] if len(sys.argv) > 2 else (sys.argv[1] if len(sys.argv) > 1 and sys.argv[1].endswith(".csv") else None)

    rows = generate_functions(elf_path)

    crlf = "\r\n"
    output_lines = [f"Name,Start,End,Size{crlf}"]
    for r in rows:
        st_hex = f"0x{r['Start']:08X}"
        end_hex = f"0x{r['End']:08X}"
        output_lines.append(f"{r['Name']},{st_hex},{end_hex},{r['Size']}{crlf}")

    if out_csv:
        with open(out_csv, "w", encoding="utf-8") as f:
            f.writelines(output_lines)
    else:
        sys.stdout.write("".join(output_lines))


if __name__ == "__main__":
    main()
